class NestedIterator {
    stack<pair<const vector<NestedInteger>*, int>> stk;
public:
    NestedIterator(vector<NestedInteger> &nestedList) {
        stk.push({&nestedList, 0});
    }

    int next() {
        hasNext();
        const vector<NestedInteger>* list = stk.top().first;
        int idx = stk.top().second;
        stk.top().second++;
        return (*list)[idx].getInteger();
    }

    bool hasNext() {
        while (!stk.empty()) {
            const vector<NestedInteger>* list = stk.top().first;
            int idx = stk.top().second;
            if (idx >= (int)list->size()) {
                stk.pop();
            } else if ((*list)[idx].isInteger()) {
                return true;
            } else {
                stk.top().second++;
                stk.push({&(*list)[idx].getList(), 0});
            }
        }
        return false;
    }
};
